def safety_threshold(payload, config=None):
    config = config or {}
    thresholds = config.get('thresholds', {})

    # Example payload: {'toxicity': 0.8}
    moderation_score = payload.get('toxicity', 0.0)

    # Default threshold for toxicity if not provided in config
    toxicity_threshold = thresholds.get('toxicity', 0.5)

    if moderation_score > toxicity_threshold:
        return {'decision': 'deny', 'reason': f'Toxicity score {moderation_score} exceeds threshold {toxicity_threshold}'}
    else:
        return {'decision': 'allow', 'reason': f'Toxicity score {moderation_score} is within threshold {toxicity_threshold}'}

from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential
from google.cloud import dlp


class SafetyClient:
    def __init__(self, provider, config):
        self.provider = provider
        self.config = config

    def get_azure_content_safety_client(self):
        if self.provider == 'azure':
            return ContentSafetyClient(self.config['endpoint'], AzureKeyCredential(self.config['api_key']))
        else:
            raise ValueError("Provider is not configured for Azure Content Safety.")

    def get_google_dlp_client(self):
        if self.provider == 'gcp':
            # Google Cloud DLP client typically gets credentials from the environment
            return dlp.DlpServiceClient()
        else:
            raise ValueError("Provider is not configured for Google Cloud DLP.")

