from dataclasses import dataclass, field
from typing import List, Dict, Any

@dataclass
class ModerationRequest:
    text: str

@dataclass
class ModerationResponse:
    toxicity: float = 0.0
    sexual_content: float = 0.0
    violence: float = 0.0
    hate_speech: float = 0.0
    harassment: float = 0.0
    self_harm: float = 0.0
    profanity: float = 0.0

@dataclass
class RedactionRequest:
    text: str

@dataclass
class RedactionResponse:
    redacted_text: str

def normalize_azure_content_safety_response(azure_response) -> ModerationResponse:
    response = ModerationResponse()
    for category in azure_response.categories_analysis:
        # Azure Content Safety categories include Hate, SelfHarm, Sexual, Violence
        # Mapping to a generic ModerationResponse structure
        if category.category == "Hate":
            response.hate_speech = category.severity / 7
        elif category.category == "SelfHarm":
            response.self_harm = category.severity / 7
        elif category.category == "Sexual":
            response.sexual_content = category.severity / 7
        elif category.category == "Violence":
            response.violence = category.severity / 7
        # Toxicity and Profanity are not directly mapped in Azure CS categories, using a placeholder/max for now
        # In a real scenario, custom classification or other models would be used for these.
        # For now, let's assume toxicity is a general measure based on max severity.
        response.toxicity = max(response.toxicity, category.severity / 7)

    return response

import google.generativeai as genai

def moderation_summary(payload, config=None):
    config = config or {}
    genai.configure(api_key=config['api_key'])

    # Using a specific model, e.g., 'gemini-pro'
    model = genai.GenerativeModel(config.get('model_name', 'gemini-pro'))

    # The moderation_decisions payload is expected to be a list of dictionaries
    # E.g., [{'text': '...', 'toxicity': 0.8, 'decision': 'deny'}, ...]
    decisions_text = "\n".join([f"Text: {d.get('text', '')}, Decision: {d.get('decision', '')}, Reason: {d.get('reason', '')}" for d in payload['moderation_decisions']])

    prompt = f"Summarize the following moderation decisions:\n\n{decisions_text}\n\nSummary:"

    try:
        response = model.generate_content(prompt)
        summary = response.text
    except Exception as e:
        summary = f"Error generating summary: {e}"

    return {'summary': summary}

from google.cloud import translate_v2 as translate

def appeal_translate(payload, config=None):
    config = config or {}
    translate_client = translate.Client()

    text_to_translate = payload['text']
    target_language = payload.get('target_language', 'en') # Default to English

    try:
        response = translate_client.translate(text_to_translate, target_language=target_language)
        translated_text = response['translatedText']
        source_language = response['detectedSourceLanguage']
    except Exception as e:
        translated_text = f"Error during translation: {e}"
        source_language = "unknown"

    return {
        'original_text': text_to_translate,
        'translated_text': translated_text,
        'source_language': source_language,
        'target_language': target_language
    }

import google.generativeai as genai

def moderation_reason_embedding(payload, config=None):
    config = config or {}
    genai.configure(api_key=config['api_key'])

    # Using a specific embedding model
    model_name = config.get('embedding_model', 'text-embedding-004')

    text_to_embed = payload['rationale']

    try:
        response = genai.embed_content(model=model_name, content=text_to_embed)
        embedding = response['embedding']
    except Exception as e:
        embedding = f"Error generating embedding: {e}"

    return {'rationale': text_to_embed, 'embedding': embedding}

from google.cloud import texttospeech

def reviewer_brief_audio(payload, config=None):
    config = config or {}
    client = texttospeech.TextToSpeechClient()

    text_to_synthesize = payload['brief_text']

    # Configure the synthesis request
    synthesis_input = texttospeech.SynthesisInput(text=text_to_synthesize)

    # Select the voice parameters
    voice = texttospeech.VoiceSelectionParams(
        language_code=config.get('language_code', 'en-US'),
        ssml_gender=texttospeech.SsmlVoiceGender.NEUTRAL # Or MALE/FEMALE
    )

    # Select the type of audio file you want returned
    audio_config = texttospeech.AudioConfig(
        audio_encoding=texttospeech.AudioEncoding.MP3
    )

    try:
        response = client.synthesize_speech(
            input=synthesis_input, voice=voice, audio_config=audio_config
        )
        # The response's audio_content is binary. In a real app, this would be saved to a file or streamed.
        # For this exercise, we'll return a placeholder or base64 encoded string (not actual base64 for simplicity).
        audio_content_base64 = "<base64_encoded_audio_content>" # In a real app, do base64.b64encode(response.audio_content).decode('utf-8')

    except Exception as e:
        audio_content_base64 = f"Error generating audio: {e}"

    return {'brief_text': text_to_synthesize, 'audio_content_base64': audio_content_base64}
